import{_ as a,o as t,c as s,ai as i}from"./chunks/framework.DQi1ytmF.js";const k=JSON.parse('{"title":"Type-safe i18n","description":"","frontmatter":{},"headers":[],"relativePath":"guide/i18n/index.md","filePath":"guide/i18n/index.md"}'),n={name:"guide/i18n/index.md"};function o(r,e,l,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/guide/i18n.md for this page in Markdown format</div><h1 id="type-safe-i18n" tabindex="-1">Type-safe i18n <a class="header-anchor" href="#type-safe-i18n" aria-label="Permalink to &quot;Type-safe i18n&quot;">​</a></h1><p><code>@craft-ts/i18n</code> is the CraftTS i18n integration. The catalogue remains a plain declarative TypeScript value, while DI-aware tokens use the existing CraftTS service contracts. A catalogue that does not use DI can still be formatted by <code>runtime.t</code>; a catalogue with DI is rendered through the reactive CraftTS translator so its dependencies are checked like component dependencies.</p><h2 id="the-contract" tabindex="-1">The contract <a class="header-anchor" href="#the-contract" aria-label="Permalink to &quot;The contract&quot;">​</a></h2><p>Six things are guaranteed, and all six are checked before the app runs.</p><table tabindex="0"><thead><tr><th>guarantee</th><th>what it costs you to break</th></tr></thead><tbody><tr><td>the key set is a <strong>closed union</strong></td><td>an unknown key does not compile — no silent <code>order.totl</code></td></tr><tr><td>every locale has the <strong>same keys with the same parameters</strong></td><td>a translation you forgot is a compile error, not a fallback</td></tr><tr><td>parameters are <strong>typed by their token</strong></td><td>a date cannot be passed where a currency amount belongs</td></tr><tr><td>a plural carries <strong>every category the locale requires</strong></td><td>Polish needs <code>one</code>/<code>few</code>/<code>many</code>/<code>other</code>; French needs <code>one</code>/<code>other</code></td></tr><tr><td>a DI-aware token declares its <strong>CraftTS services</strong></td><td>a missing provider is a compile error at the component/route boundary</td></tr><tr><td>a token declared with a <strong>schema</strong> types its own input</td><td>the call site passes what the schema parses, not what the formatter wants</td></tr></tbody></table><p>The usual failure mode of a translation layer is that all of these are runtime concerns: a missing key renders its own name, a wrong parameter renders <code>[object Object]</code>, and a missing plural category renders the wrong branch to the users of one locale only. None of that is observable from the code that calls <code>t</code>.</p><h2 id="the-shape-of-it" tabindex="-1">The shape of it <a class="header-anchor" href="#the-shape-of-it" aria-label="Permalink to &quot;The shape of it&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/i18n/</span></span>
<span class="line"><span>  catalog.ts          the reference locale — defineCatalog + msg + plural</span></span>
<span class="line"><span>  locales/fr-FR.ts    every other locale — defineLocaleLike</span></span>
<span class="line"><span>  project-tokens.ts   business tokens: defineToken / defineTokenFactory</span></span>
<span class="line"><span>  runtime.ts          createI18nRuntime, and the reactive binding</span></span></code></pre></div><p>A key is its dotted path: <code>order.total</code> reaches <code>{ order: { total: msg</code>…<code> } }</code>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./catalog.html">The catalogue</a> — <code>defineCatalog</code>, <code>msg</code>, <code>plural</code>, <code>defineLocale</code>, <code>defineLocaleLike</code>.</li><li><a href="./tokens.html">Tokens</a> — the shipped semantic tokens, and how to add your own.</li><li><a href="./runtime.html">The runtime</a> — <code>createI18nRuntime</code>, <code>t</code>, <code>bind</code>, lazy locales.</li><li><a href="./effect.html">With Effect</a> — <code>@craft-ts/i18n-effect</code>.</li></ul><p>Two checks belong in CI, and <code>craft create</code> wires both:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n:test</span></span></code></pre></div><p>A working example lives in the demo, at <code>apps/demo/src/app/examples/i18n/</code>.</p><h2 id="guard-visible-text-in-craft-templates" tabindex="-1">Guard visible text in Craft templates <a class="header-anchor" href="#guard-visible-text-in-craft-templates" aria-label="Permalink to &quot;Guard visible text in Craft templates&quot;">​</a></h2><p><code>craft create</code> enables this preset for every project generated <strong>with</strong> i18n — its own pages already take their copy from the catalogue. A project generated without i18n never sees the rule. To add it by hand to an existing application:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> craftRules </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@craft-ts/dev-tools/eslint-rules&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    plugins: { </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;craft-ts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: craftRules },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    rules: { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">craftRules.configs.i18n.rules },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p><code>craft-ts/require-i18n-text</code> reports static text in visible headings, paragraphs, labels, buttons, links and options, plus visible <code>placeholder</code>, <code>aria-label</code> and <code>title</code> attributes — and it looks <em>inside</em> the visible position, so <code>p(&#39;Total: &#39; + t(&#39;cart.total&#39;))</code>, <code>span(\`Total: \${amount}\`)</code>, <code>label(isNew ? &#39;New&#39; : &#39;Returning&#39;)</code>, <code>p(name || &#39;Anonymous&#39;)</code> and a literal in a children array are reported too. Only what carries letters counts: <code>first + &#39; &#39; + last</code> is glue between values, not copy. Dynamic business values, <code>i18n.t(...)</code>, its key and parameters, a generator child and catalogue files are accepted. Server files and tests are excluded so technical messages and assertions can remain literal. The rule stays separate from the recommended preset, because it only makes sense once the catalogue is the application&#39;s source of truth — which is exactly the condition <code>craft create</code> checks when it decides to enable it.</p>`,19)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
